private async validateUserId(
  userId: string | undefined,
  tx?: any,
): Promise<string | undefined> {
  if (!userId) return undefined;

  // If userId is 'system', ensure system user exists and return its ID
  if (userId === "system") {
    return await this.ensureSystemUser(tx);
  }

  try {
    const prismaClient = tx || this.prisma;  // Use transaction client if provided
    const userExists = await prismaClient.user.findUnique({
      where: { id: userId },
      select: { id: true },
    });

    if (!userExists) {
      this.logger.warn(
        `User ID ${userId} not found in database, using system user instead`,
      );
      return await this.ensureSystemUser(tx);
    }

    return userId;
  } catch (userCheckError) {
    this.logger.warn(
      `Failed to validate user ID ${userId}, using system user instead:`,
      userCheckError,
    );
    return await this.ensureSystemUser(tx);
  }
}
```

