private detectChangeAreas(commits: GitHubCommit[]): {
  hasBackend: boolean;
  hasFrontend: boolean;
} {
  const backendPatterns = [
    /\bbackend\b/i,
    /\bapi\b/i,
    /\bserver\b/i,
    /\bprisma\b/i,
    /\bdatabase\b/i,
    /apps\/whk-wms\//i,
    /\.service\.ts/i,
    /\.controller\.ts/i,
    /\.resolver\.ts/i,
    /\.module\.ts/i,
  ];

  const frontendPatterns = [
    /\bfrontend\b/i,
    /\bui\b/i,
    /\bcomponent/i,
    /\breact\b/i,
    /apps\/whk-wms-front-end\//i,
    /\.tsx$/i,
    /\bpage\b/i,
  ];

  for (const commit of commits) {
    const message = commit.commit.message;
    if (backendPatterns.some((pattern) => pattern.test(message))) {
      hasBackend = true;
    }
    if (frontendPatterns.some((pattern) => pattern.test(message))) {
      hasFrontend = true;
    }
    if (hasBackend && hasFrontend) break;
  }

  // Default to both if couldn't determine
  if (!hasBackend && !hasFrontend && commits.length > 0) {
    hasBackend = true;
    hasFrontend = true;
  }
  return { hasBackend, hasFrontend };
}
```

### 4. **Commit Analysis Between Tags**

`fetchCommitsForRelease()` at `lines 284-318` fetches commits by comparing consecutive releases:

```
