### 2. **Validation Decision Logic**

**apps/whk-wms/src/trust-mode/trust-mode-config.service.ts:110-125** - `shouldProcessAndroidSyncRecord`

```typescript
async shouldProcessAndroidSyncRecord(createdAt: Date): Promise<boolean> {
  // Always sync from Redis for consistency across processes
  await this.loadFromRedis();

  if (!this.config.enabled) {
    return true; // Trust mode OFF - process all records
  }

  if (!this.config.cutoffDate) {
    return true; // No cutoff set - process all records
  }

  // Trust mode ON - only process records BEFORE cutoff date
  return createdAt < this.config.cutoffDate;
}
```

**Filter Logic**: Records created **BEFORE** the cutoff date are processed; records created **AFTER** are silently skipped.

### 3. **Integration into Android Sync Processing**

**apps/whk-wms/src/androidSyncInbox/android-sync.processor.ts:316-341** - `shouldProcessRecord` method

```typescript
private async shouldProcessRecord(record: any): Promise<boolean> {
  if (!(await this.trustModeConfigService.isTrustModeEnabled())) {
    return true; // Trust mode disabled, process all records
  }

  const recordCreatedAt = new Date(record.createdAt);
  const shouldProcess =
    await this.trustModeConfigService.shouldProcessAndroidSyncRecord(
      recordCreatedAt,
    );

  if (!shouldProcess) {
    const config = this.trustModeConfigService.getConfigForLogging();
    this.logger.log(
      `Trust Android Scans Mode: Skipping record created at ${recordCreatedAt.toISOString()} (cutoff: ${config.cutoffDate})`,
    );
  }

  return shouldProcess;
}
```

Called early in the job processing pipeline (line 324):
```typescript
