async setTrustMode(request: SetTrustModeRequestDto): Promise<TrustModeStatusDto> {
  // Validate cutoff date is not in future
  const cutoffDate = new Date(request.cutoffDate);
  if (cutoffDate > new Date()) {
    throw new Error('Cutoff date cannot be in the future');
  }

  const newConfig = {
    enabled: true,
    cutoffDate,
    description: request.description,
    enabledAt: new Date(),
  };

  // Persist to Redis for cross-process consistency (24-hour TTL)
  await this.redisClient.setex(
