```typescript
async updateBarrel<T extends Prisma.BarrelUpdateArgs>(
  args: Prisma.SelectSubset<T, Prisma.BarrelUpdateArgs>,
  barrelId?: string,
): Promise<PrismaBarrel> {
  // Detect if modifying location fields
  const modifyingStorageLocation =
    args.data.location?.connect ||
    args.data.location?.disconnect ||
    "locationId" in args.data;

  const modifyingHoldingLocation =
    args.data.holdingLocation?.connect ||
    args.data.holdingLocation?.disconnect ||
    "holdingLocationId" in args.data;

  // If modifying location or disposition, fetch current state
  if (modifyingStorageLocation || modifyingHoldingLocation || modifyingDisposition) {
    const currentBarrel = await this.prisma.barrel.findUnique({
      where: args.where,
      select: { locationId: true, holdingLocationId: true, disposition: true },
    });

    if (currentBarrel) {
      // Calculate final state AFTER update (before actually executing update)
      // Example: if updating locationId to null, willHaveStorageLocation = false
      let willHaveStorageLocation: boolean;
      if (args.data.location?.disconnect) {
        willHaveStorageLocation = false;  // Line 640: disconnecting location
      } else if ("locationId" in args.data) {
        willHaveStorageLocation =
          args.data.locationId !== null && args.data.locationId !== undefined;
      } else if (args.data.location?.connect) {
        willHaveStorageLocation = true;
      } else {
        willHaveStorageLocation = 
          currentBarrel.locationId !== null && currentBarrel.locationId !== undefined;
      }

      let willHaveHoldingLocation: boolean;
      if (args.data.holdingLocation?.disconnect) {
        willHaveHoldingLocation = false;
      } else if ("holdingLocationId" in args.data) {
        willHaveHoldingLocation =
          args.data.holdingLocationId !== null && args.data.holdingLocationId !== undefined;
      } else if (args.data.holdingLocation?.connect) {
        willHaveHoldingLocation = true;
      } else {
        willHaveHoldingLocation = 
          currentBarrel.holdingLocationId !== null && 
          currentBarrel.holdingLocationId !== undefined;
      }

      // Throw BEFORE executing update
      if (willHaveStorageLocation && willHaveHoldingLocation) {
        throw new BarrelLocationConflictException();  // Line 669
      }
    }
  }

  return this.prisma.barrel.update(args);
}
```

**Critical pattern**: Validates the **final state** after update, not just the current input - this prevents updates that would create conflicts.

