  sync              Boolean         @default(false)
  error             String?
  receivedAt        DateTime        @default(now())
  updatedAt         DateTime        @updatedAt
  warehouseJobId    String?

  @@id([deviceName, inboxId])      // Composite primary key
  @@index([deviceName])
  @@index([eventType])
  @@index([sync])
  @@index([receivedAt])
  @@index([warehouseJobId])
  @@index([barrelSN])
  @@index([sync, receivedAt])
}
```

**Duplicate definition** (line 1125): A record with the same `(deviceName, inboxId)` pair is considered a duplicate.

### 2. **Atomic Duplicate Detection with ON CONFLICT DO NOTHING RETURNING**

**apps/whk-wms/src/androidSyncInbox/android-sync-inbox.service.ts:38-210** - `saveToInbox` method

```typescript
/**
 * DUPLICATE HANDLING: Returns only newly created records when duplicates are encountered:
 * - Uses individual upsert operations with ON CONFLICT DO NOTHING RETURNING
 * - Atomically identifies actually inserted records without race conditions
 * - Eliminates timestamp-based queries that are prone to clock skew and race conditions
 * - Ensures return value semantics match method expectations (newly created records only)
 */
async saveToInbox(syncData: AndroidSyncDto): Promise<AndroidSyncInbox[]> {
  const { metadata, data } = syncData;
  const totalRecords = data.length;

  // Track successfully inserted records
  const insertedRecords: AndroidSyncInbox[] = [];

  try {
    // Process in chunks to avoid large transactions
    for (let i = 0; i < inboxRecords.length; i += this.CHUNK_SIZE) {
      const chunk = inboxRecords.slice(i, i + this.CHUNK_SIZE);

      // Use individual upsert operations to reliably identify inserted records
      const chunkInsertPromises = chunk.map(async (record) => {
        try {
          // Use raw SQL with ON CONFLICT DO NOTHING RETURNING to atomically
          // identify if this specific record was actually inserted
          const result = await this.prisma.$queryRaw<AndroidSyncInbox[]>`
            INSERT INTO "AndroidSyncInbox" (
              "deviceName", "inboxId", "barrelSN", "locationString", 
              "eventType", "jsonEntityPayload", "operator", "createdAt", 
              "sync", "error", "warehouseJobId", "receivedAt", "updatedAt"
            ) VALUES (
              ${record.deviceName}, ${record.inboxId}, ${record.barrelSN}, ${record.locationString},
              ${record.eventType}, ${jsonPayload}::jsonb, ${record.operator}, ${record.createdAt},
              ${record.sync}, ${record.error}, ${record.warehouseJobId}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
            )
            ON CONFLICT ("deviceName", "inboxId") DO NOTHING
            RETURNING *
          `;

          // Line 130: If RETURNING returns a record, it was actually inserted (not a duplicate)
          return result.length > 0 ? result[0] : null;
        } catch (error) {
          this.logger.error(
            `Failed to insert individual record ${record.deviceName}:${record.inboxId}`,
            { error, record }
          );
          return null;
        }
      });

      // Line 148: Wait for all insertions in this chunk to complete
      const chunkResults = await Promise.all(chunkInsertPromises);

      // Line 153: Filter out null results (duplicates or errors)
      const chunkInsertedRecords = chunkResults.filter(
        (record): record is AndroidSyncInbox => record !== null,
      );

      insertedRecords.push(...chunkInsertedRecords);
      totalInserted += chunkInsertedRecords.length;

      const skippedCount = chunk.length - chunkInsertedRecords.length;
      this.logger.debug(
        `Chunk completed: ${chunkInsertedRecords.length} records inserted, ${skippedCount} duplicates/errors skipped`
      );
    }
  }
}
```

**Key mechanism** (line 126): `ON CONFLICT ("deviceName", "inboxId") DO NOTHING RETURNING *`
- Attempts to insert the record
- If a conflict on the composite key occurs → silently skips insertion (DO NOTHING)
- RETURNING clause returns the newly inserted record (or nothing if conflicted)
- Result.length > 0 atomically indicates successful insertion without race conditions

### 3. **Deadlock Prevention: Chunked Processing Strategy**

**apps/whk-wms/src/androidSyncInbox/android-sync-inbox.service.ts:18-21, 92-182**

```typescript
/** Number of records to process per chunk to reduce database lock duration */
private readonly CHUNK_SIZE = 50;        // Line 18

/** Delay between processing chunks to reduce database pressure */
private readonly CHUNK_DELAY_MS = 100;   // Line 21

async saveToInbox(syncData: AndroidSyncDto): Promise<AndroidSyncInbox[]> {
  // Process in chunks to avoid large transactions (line 91)
  for (let i = 0; i < inboxRecords.length; i += this.CHUNK_SIZE) {
    const chunk = inboxRecords.slice(i, i + this.CHUNK_SIZE);
    const chunkNumber = Math.floor(i / this.CHUNK_SIZE) + 1;
    const totalChunks = Math.ceil(inboxRecords.length / this.CHUNK_SIZE);

    // Wait for all insertions in this chunk
    const chunkResults = await Promise.all(chunkInsertPromises);

    // Add delay between chunks to reduce database pressure (line 173)
    if (i + this.CHUNK_SIZE < inboxRecords.length) {
      this.logger.debug(`Waiting ${this.CHUNK_DELAY_MS}ms before next chunk`);
      await new Promise((resolve) =>
        setTimeout(resolve, this.CHUNK_DELAY_MS),
      );
    }
  }
}
```

**Deadlock prevention mechanisms**:
1. **Line 18**: Chunk size of 50 records → smaller transactions = shorter lock duration
2. **Line 21**: 100ms delay between chunks → prevents lock contention accumulation
3. **Line 173-178**: Explicit sleep between chunks allows other operations to acquire locks
4. **Line 46 in comments**: "Prevent all records from having identical createdAt timestamps" → spreads timestamps across multiple chunks, avoiding timestamp-based conflicts

### 4. **Why This Approach Prevents Deadlocks**

**Deadlock Risk Mitigation** (lines 40-46):

```
DEADLOCK MITIGATION: This method processes large batches in smaller chunks to:
- Reduce transaction size and lock duration
- Prevent all records from having identical createdAt timestamps
- Improve database resource utilization
- Enable better error isolation
```

**Specific benefits**:
- **Smaller transactions**: 50 records per chunk vs. potentially hundreds → locks released faster
- **Lock interleaving**: 100ms delays allow concurrent operations to acquire locks in between chunks
- **Timestamp distribution**: Records get `createdAt` over multiple chunks → prevents single-second batch causing index lock contention
- **Isolated failures**: If chunk N fails, chunk N+1 can still proceed independently (line 187: `continue`)

### 5. **Duplicate Handling Return Semantics**

**apps/whk-wms/src/androidSyncInbox/android-sync-inbox.service.ts:153-165**

```typescript
// Filter out null results (duplicates or errors) and collect successful insertions
const chunkInsertedRecords = chunkResults.filter(
  (record): record is AndroidSyncInbox => record !== null,
);

insertedRecords.push(...chunkInsertedRecords);
totalInserted += chunkInsertedRecords.length;

const skippedCount = chunk.length - chunkInsertedRecords.length;
this.logger.debug(
  `Chunk ${chunkNumber}/${totalChunks} completed: ${chunkInsertedRecords.length} records inserted, ${skippedCount} duplicates/errors skipped`,
);
```

**Return value semantics**: Only newly inserted records are returned - duplicates are filtered out (line 153) and logged as "skipped". This matches method contract expectations (line 55: "Array of newly inserted AndroidSyncInbox records (excludes duplicates)").

### 6. **Race Condition Elimination**

**Why NOT timestamp-based queries** (lines 48-52):

```
- Eliminates timestamp-based queries that are prone to clock skew and race conditions
```

**Problem with timestamp queries**:
```sql
-- PROBLEMATIC: Race condition window
INSERT INTO AndroidSyncInbox VALUES (...);
SELECT * FROM AndroidSyncInbox WHERE createdAt > NOW() - INTERVAL 1;
-- Between INSERT and SELECT, records could be modified or deleted
```

**Solution with ON CONFLICT RETURNING**:
```sql
-- ATOMIC: No race condition
INSERT INTO AndroidSyncInbox VALUES (...)
ON CONFLICT DO NOTHING
RETURNING *;
-- Result is either the inserted record or nothing - atomic decision
```

`★ Insight ─────────────────────────────────────`
1. **Atomic Duplicate Detection**: `ON CONFLICT DO NOTHING RETURNING` eliminates the need for race-prone timestamp queries - the database itself answers "was this actually inserted?" in a single atomic operation
2. **Chunking + Delays = Deadlock Prevention**: Small transactions (50 records) with inter-chunk delays (100ms) create natural lock release windows, allowing concurrent operations to proceed without waiting for massive multi-second locks
3. **Timestamp Distribution**: Spreading inserts across multiple chunks with delays prevents all records from competing for the same index locks at the same timestamp, reducing B-tree contention on createdAt/receivedAt indexes
`─────────────────────────────────────────────────`

## ANSWER TO QUESTION 39: Trace the data flow for resolving canonical lot from a lot variation serial number

The system resolves canonical lots through a **three-stage process**: serial number extraction, variation lookup, and canonical lot resolution. Here's the complete data flow:

### 1. **Entry Point: Serial Number Received**

**apps/whk-wms/src/barrelEvent/barrelEvent.service.ts:1925-1975** - `findOrCreateBarrel` method

When a barrel serial number arrives (from Android sync, inventory upload, or API):

```typescript
// Line 1925: Start of normalization
// TEC-611: Normalize serial number to handle lot variations

// Line 1944: Extract lot code from serial
const lotNumber = this.extractLotCodeFromSerial(
  barrelSN,
  skipNormalization,
);

if (!skipNormalization && snParts.length >= 2) {
  this.logger.debug(`[TEC-611] Checking if lot code is a variation`, {
    potentialLotCode: lotNumber,
    originalSerial: barrelSN,
  });

  // Line 1949: Check if this lot code is a variation and resolve to canonical lot
  // TEC-611: Use prisma client directly (without tx) to avoid transaction isolation issues
  // Lot variations are semi-static data that should be visible regardless of transaction state
  const canonicalLot =
    await this.lotVariationService.findLotByNumberOrVariation(
      lotNumber,
      // Note: Intentionally not passing tx - see TEC-611 comments above
    );

  if (canonicalLot && canonicalLot.lotNumber !== lotNumber) {
    // This is a variation, reconstruct serial with canonical lot
    const lotPartsUsed = snParts.length >= 3 ? 2 : 1;
    const remainingParts = snParts.slice(lotPartsUsed).join(".");
    normalizedSerial = `${canonicalLot.lotNumber}.${remainingParts}`;

    this.logger.debug(
      `[TEC-611] Normalized serial number via lot variation: ${barrelSN} -> ${normalizedSerial}`,
      {
        lotPartsUsed,
        remainingParts,
        snParts,
      },
    );
  }
}
```

### 2. **Lot Variation Lookup: Database Query**

**apps/whk-wms/src/lotVariation/lotVariation.service.ts:17-59** - `findLotByNumberOrVariation` method

This is the **core resolution method**:

```typescript
/**
 * Find a lot by exact lot number or by variation.
 * PRIORITIZES LotVariation lookup first, then falls back to exact Lot.lotNumber match.
 * This ensures that when both a real lot and a variation exist for the same number,
 * the canonical lot is always returned (fixing TEC-1047).
 */
async findLotByNumberOrVariation(
  lotNumber: string,
  tx?: Prisma.TransactionClient,
): Promise<(Lot & { recipe?: any }) | null> {
  const client = tx || this.prismaRead;

  // Line 33: CHANGED (TEC-1047): Check variation mapping FIRST
  // This ensures we always use canonical lots when variations exist
  const variation = await client.lotVariation.findFirst({
    where: { variationNumber: lotNumber },
    include: {
      canonicalLot: {
        include: { recipe: true },
      },
    },
  });

  if (variation) {
    this.logger.log(
      `Found lot via variation: ${lotNumber} -> ${variation.canonicalLot.lotNumber}`,
    );
    return variation.canonicalLot;  // Line 48: Return canonical lot
  }

  // Line 51: FALLBACK: Try exact match on lot number
  const exactLot = await client.lot.findFirst({
    where: { lotNumber },
    include: { recipe: true },
  });

  if (exactLot) {
    this.logger.log(`Found exact lot match: ${lotNumber}`);
  }

  return exactLot;
}
```

**Database queries executed**:
1. **Query 1** (line 34-39): Search `LotVariation` table for `variationNumber = lotNumber`
   - If found → return `variation.canonicalLot` (the canonical Lot record)
   - If not found → proceed to Query 2
2. **Query 2** (line 53-57): Search `Lot` table for exact `lotNumber` match
   - Return the lot if found, null otherwise

### 3. **Data Model: LotVariation Structure**

**apps/whk-wms/prisma/schema.prisma:404-417** - LotVariation model

