### 4. **Serial Number Normalization Flow**

**apps/whk-wms/src/staging/inventory-check-staging.service.ts:37-95** - Serial extraction

The system handles three serial formats:

```typescript
/**
 * Extracts lot number from barrel serial number
 * Handles various serial number formats:
 * - 3-part: "24H02B.10.0278" → "24H02B.10" (canonical lot with sublot)
 * - 2-part: "25G29AB.0001" → "25G29AB" (lot variation, barrel number only)
 */
async resolveLotFromSerialNumber(serialNumber: string): Promise<{
  success: boolean;
  lot?: Lot;
  error?: string;
}> {
  // Line 45: Extract lot number from serial number
  const lotNumber = this.extractLotNumberFromSerial(serialNumber);

  if (!lotNumber) {
    return { success: false, error: `Cannot extract lot number from serial: ${serialNumber}` };
  }

  // Line 54: Use LotVariationService to resolve canonical lot
  // This handles both exact lot matches and lot variation mappings
  const lot = await this.lotVariationService.findLotByNumberOrVariation(
    lotNumber,
  );

  if (!lot) {
    return {
      success: false,
      error: `Lot ${lotNumber} not found in system (checked both exact and variations)`,
    };
  }

  return { success: true, lot };
}

private extractLotNumberFromSerial(serialNumber: string): string | null {
  const dotParts = serialNumber.split(".");
  if (dotParts.length >= 3) {
    // 3-part format: LOT.SUBLOT.BARREL → extract "LOT.SUBLOT"
    if (dotParts[0] && dotParts[1]) {
      return `${dotParts[0]}.${dotParts[1]}`;
    }
  } else if (dotParts.length === 2) {
    // 2-part format: LOT.BARREL → extract just "LOT"
    return dotParts[0];
  }
  return null;
}
```

