### 6. **GraphQL Resolution: Display to User**

**apps/whk-wms/src/barrel/barrel.resolver.ts:501-541** - Barrel variation resolver

Returns the variation mapping to the user:

```typescript
/**
 * Returns the lot variation that is actively in use by this barrel
 * When set, the barrel is using a variation serial number; when null, it uses the canonical lot number
 */
@graphql.ResolveField(() => LotVariationDto, { nullable: true })
async lotVariation(
  @graphql.Parent() barrel: Barrel & { lotVariationId?: string | null },
): Promise<LotVariationDto | null> {
  if (!barrel.lotVariationId) {
    return null;
  }

  // Use DataLoader to batch lookups and prevent N+1 queries
  const variation = await this.lotVariationLoader.load(barrel.lotVariationId);

  if (!variation) {
    return null;
  }

  return {
    id: variation.id,
    variationNumber: variation.variationNumber,          // What was scanned
    canonicalLotId: variation.canonicalLotId,
    canonicalLot: {
      id: variation.canonicalLot.id,
      lotNumber: variation.canonicalLot.lotNumber,       // Resolved canonical lot
    },
    notes: variation.notes,
    createdAt: variation.createdAt,
    createdBy: variation.createdBy,
  };
}
