    })().catch((error) => {
      this.logger.error(
        `Error processing cache invalidation events: ${error}`,
      );
    });

    this.logger.log(
      `📡 Subscribed to distributed cache invalidation channel: ${this.CACHE_INVALIDATION_CHANNEL}`,
    );
