    const barrelAnalysis = await this.step2IdentifyBarrelNumber(
      lotCandidate.lotId,
      lotCandidate.lotNumber,
      locationParts,
      adjacentBarrels,
      radius,
    );

    // Combine lot score (70%) + barrel score (30%)
    predictions.push({
