```typescript
async step2IdentifyBarrelNumber(
  lotId: string,
  lotNumber: string,
  locationParts: LocationParts,
  adjacentBarrels: AdjacentBarrel[],
  radius: number,
): Promise<{ suggestedSerial, barrelScore, barrelReasoning, suggestionType, ... }> {
  const lotBarrels = adjacentBarrels.filter((b) => b.lotId === lotId);

  // Strategy 1: Perfect Sequential Pattern Detection (Lines 2107-2130)
  // Detects pattern: leftSerial → expectedSerial → rightSerial
  const sequentialPattern = this.detectSequentialPattern(
    lotBarrels,
    locationParts.position,
    lotNumber,
  );

  if (sequentialPattern && sequentialPattern.patternType === 'perfect') {
    return {
      suggestedSerial: sequentialPattern.expectedSerial,
      barrelScore: 95,  // Highest confidence
      barrelReasoning: `Perfect sequential pattern detected: ${leftSerial} → ${expectedSerial} → ${rightSerial}`,
      suggestionType: existingBarrel ? 'EXISTING' : 'HYPOTHETICAL',
    };
  }

  // Strategy 2: Gap Detection in Sequential Range (Lines 2133-2168)
  // Finds missing barrels in sequence within ±radius
  const gaps = this.detectGapsInSequentialRange(
    lotBarrels.map((b) => ({ serialNumber: b.serialNumber, position: b.position })),
    lotNumber,
    locationParts.position - radius,
    locationParts.position + radius,
  );

  if (gaps.length > 0) {
    // Use gap closest to target position
    const closestGap = gaps.reduce((closest, current) =>
      Math.abs(current.expectedPosition - locationParts.position) <
      Math.abs(closest.expectedPosition - locationParts.position)
        ? current
        : closest,
    );

    return {
      suggestedSerial: closestGap.expectedSerial,
      barrelScore: 80,  // High confidence
      barrelReasoning: `Gap detected in sequential range: missing ${closestGap.expectedSerial} at position ${closestGap.expectedPosition}`,
      suggestionType: existingBarrel ? 'EXISTING' : 'HYPOTHETICAL',
    };
  }

  // Strategy 3: Next Sequential Number (Lines 2171-2200)
  // Fallback: Generate next number in sequence
  const sequentialNumbers = lotBarrels
    .map((b) => this.extractSequentialNumber(b.serialNumber))
    .filter((n): n is number => n !== null)
    .sort((a, b) => a - b);

  let nextNumber = 1;
  if (sequentialNumbers.length > 0) {
    nextNumber = sequentialNumbers[sequentialNumbers.length - 1] + 1;
  }

  const suggestedSerial = this.formatSequentialSerial(lotNumber, nextNumber);

  return {
    suggestedSerial,
    barrelScore: 60,  // Moderate confidence
    barrelReasoning: `Next sequential number in lot ${lotNumber}: ${suggestedSerial}`,
    suggestionType: isSemanticSerial ? '.9xxx' : existingBarrel ? 'EXISTING' : 'HYPOTHETICAL',
  };
}
