**FilterPresets.tsx** (lines 1-97) enables saving and loading filter combinations:

```typescript
const LAST_KEY = 'inventory.filters'
const PRESETS_KEY = 'inventory.presets'

type FiltersMap = Record<string, string>

export default function FilterPresets() {
  const [presets, setPresets] = useState<Array<{ name: string; filters: FiltersMap }>>([])\n
  // Load last
  const loadLast = () => {
    const raw = localStorage.getItem(LAST_KEY)
    if (!raw) return
    const saved = JSON.parse(raw) as FiltersMap
    applyFilters(saved)
  }

  // Save current filters as preset
  const saveAs = () => {
    const name = window.prompt('Save current filters as:')
    if (!name) return
    const next = [...presets.filter(p => p.name !== name), { name, filters: currentFilters }]
    setPresets(next)
    localStorage.setItem(PRESETS_KEY, JSON.stringify(next))
  }

  // Load preset by name
  const loadPreset = (name: string) => {
    const p = presets.find(x => x.name === name)
    if (!p) return
    applyFilters(p.filters)
  }
```

**Preset storage strategy**:
- Named filter combinations stored as JSON arrays in localStorage
- `PRESETS_KEY`: `inventory.presets` → `[{name, filters}, ...]`
- `LAST_KEY`: `inventory.filters` → last used filter combination
