**Dynamic mutation methods** (lines 53-67):
```typescript
setCorrelationId(correlationId: string): void {
  const store = this.asyncLocalStorage.getStore();
  if (store) {
    store.correlationId = correlationId;  // Mutate in-place
  }
}

setOperationMetadata(metadata: Record<string, any>): void {
  const store = this.asyncLocalStorage.getStore();
  if (store) {
    if (!store.operationMetadata || typeof store.operationMetadata !== "object") {
      store.operationMetadata = {};
    }
    Object.assign(store.operationMetadata, metadata);  // Merge metadata
  }
}
```

