### Bulk Operations Pattern: Creating Both Transaction Types

**apps/whk-wms/src/barrelOwnership/barrelOwnership.service.ts (lines 642-776)**

The `bulkUpdateOwnership` method demonstrates the two-layer pattern:

```typescript
async bulkUpdateOwnership(
  operation: BulkOwnershipOperationInput,
  establishedBy: string,
): Promise<BulkOwnershipOperationResponse> {
  const operationId = createId();

  // Step 1: Create GroupTransaction to group the operation
  const transactionGroup = await this.createTransactionGroup(
    EnumGroupTransactionType.ADJUSTMENT,  // High-level operation type
    establishedBy,
    {
      notes: operation.notes,
      transferReasonId: operation.transferReasonId,
      operationId,  // UUID linking all related transactions
      batchId: operation.batchId || `bulk_update_${operationId}`,
      metadata: operation.filter  // Store the filter criteria for audit trail
        ? JSON.parse(JSON.stringify({
            filter: operation.filter,
            replaceExisting: operation.replaceExisting,
          }))
        : undefined,
    },
  );

  // Step 2: For each barrel, create OwnershipTransaction linked to GroupTransaction
  for (const barrel of barrels) {
    try {
      await this.prisma.$transaction(async (tx) => {
        // ... update ownership records ...

        // Create OwnershipTransaction for EACH ownership created
        await Promise.all(
          operation.ownerships.map((ownership: OwnershipUpdate) =>
            this.createOwnershipTransaction(
              isJointOwnership
                ? EnumOwnershipTransactionType.BULK_JOINT_ESTABLISHMENT
                : EnumOwnershipTransactionType.BULK_ESTABLISHMENT,
              barrel.id,
              establishedBy,
              {
                toCustomerId: ownership.customerId,
                ownershipPercentage: ownership.percentage,
                transferReasonId: operation.transferReasonId,
                notes: operation.notes,
                jointOwnershipGroupId,
                operationId,  // Links back to bulk operation
                batchId: operation.batchId || `bulk_update_${operationId}`,
                groupId: transactionGroup.id,  // Explicitly links to GroupTransaction
              },
              tx,
            ),
          ),
        );
      });
    } catch (error) {
      // Track errors per barrel
      errors.push({
        barrelId: barrel.id,
        serialNumber: barrel.serialNumber,
        error: "Update failed",
        details: error instanceof Error ? error.message : String(error),
      });
    }
  }
}
```

### Transfer-Specific Pattern

**apps/whk-wms/src/barrelOwnership/barrelOwnership.service.ts (lines 778-824)**

For bulk transfers, GroupTransaction tracks the customer-to-customer flow:

```typescript
async bulkTransferOwnership(
  operation: BulkTransferOwnershipInput,
  transferredBy: string,
): Promise<BulkOwnershipOperationResponse> {
  const operationId = createId();

  // Create GroupTransaction with FROM/TO customer context
  const transactionGroup = await this.createTransactionGroup(
    EnumGroupTransactionType.OWNERSHIP_TRANSFER,  // Operation type
    transferredBy,
    {
      fromCustomerId: operation.fromCustomerId,  // Source customer
      toCustomerId: operation.toCustomerId,      // Destination customer
      notes: operation.notes,
      transferReasonId: operation.transferReasonId,
      operationId,
      batchId: operation.batchId || `bulk_transfer_${operationId}`,
      metadata: operation.filter
        ? JSON.parse(JSON.stringify({ filter: operation.filter }))
        : undefined,
    },
  );

  // For each barrel, delegate to transferOwnership (lines 352-400)
  // which creates an OwnershipTransaction linked back to groupId
  for (const barrel of barrels) {
    try {
      await this.transferOwnership(
        barrel.id,
        operation.fromCustomerId,
        operation.toCustomerId,
        transferredBy,
        operation.transferPercentage,
        operation.notes,
        operation.transferReasonId,
        {
          groupId: transactionGroup.id,  // Links to GroupTransaction
          operationId,
          batchId: operation.batchId || `bulk_transfer_${operationId}`,
        },
      );
      // Track success
      successes.push({
        barrelId: barrel.id,
        serialNumber: barrel.serialNumber,
        ownershipIds: [],
        operation: "transfer",
      });
    } catch (error) {
      // Track failures
      errors.push({
        barrelId: barrel.id,
        serialNumber: barrel.serialNumber,
        error: "Transfer failed",
        details: error instanceof Error ? error.message : String(error),
      });
    }
  }

  return {
    totalRequested: barrels.length,
    successfulUpdates: successes.length,
    failedUpdates: errors.length,
    successes,
    errors,
    operationId,
    completedAt: new Date(),
  };
}
```

