### Integration with DataLoader

**apps/whk-wms/src/barrel/barrel-ownership.loader.ts (lines 1-105)**

The actual GraphQL optimization pattern uses DataLoader to batch requests:

```typescript
/**
 * DataLoader for batching BarrelOwnership queries to prevent N+1 query problems.
 *
 * This loader is REQUEST-scoped, meaning a new instance is created for each GraphQL request.
 * It batches multiple barrel ownership lookups into a single database query.
 *
 * Example:
 * Instead of executing 50 queries for 50 barrels:
 *   SELECT * FROM BarrelOwnership WHERE barrelId = 'barrel-1'
 *   SELECT * FROM BarrelOwnership WHERE barrelId = 'barrel-2'
 *   ...
 *
 * It executes a single batched query:
 *   SELECT * FROM BarrelOwnership WHERE barrelId IN ('barrel-1', 'barrel-2', ...)
 *
 * This solves TEC-1122: Connection pool exhaustion due to N+1 queries.
 */
@Injectable({ scope: Scope.REQUEST })
export class BarrelOwnershipLoader {
  private readonly activeOwnershipsLoader: DataLoader<
    string,
    (BarrelOwnership & { customer: Customer })[]
  >;

  constructor(private readonly prisma: PrismaService) {
    // Loader batches multiple barrel IDs into ONE query
    this.activeOwnershipsLoader = new DataLoader(
      async (barrelIds: readonly string[]) => {
        const ownerships = await this.prisma.barrelOwnership.findMany({
          where: {
            barrelId: { in: [...barrelIds] },  // Batches all IDs at once
            validTo: null,
            validFrom: { lte: new Date() },
          },
          include: { customer: true },
          orderBy: { validFrom: "desc" },
        });

        // Group ownerships by barrelId
        const ownershipMap = new Map<string, (BarrelOwnership & { customer: Customer })[]>();
        barrelIds.forEach((id) => ownershipMap.set(id, []));  // Initialize all IDs

        // Populate with actual ownerships
        ownerships.forEach((ownership) => {
          const list = ownershipMap.get(ownership.barrelId);
          if (list) list.push(ownership);
        });

        // Return results in input order (required by DataLoader)
        return barrelIds.map((id) => ownershipMap.get(id) || []);
      },
    );
  }

  async loadActiveOwnerships(barrelId: string): Promise<(BarrelOwnership & { customer: Customer })[]> {
    return this.activeOwnershipsLoader.load(barrelId);
  }
}
```

### Resolver Integration Pattern

**apps/whk-wms/src/barrel/barrel.resolver.ts (lines 391-425)**

The resolver uses the DataLoader, which internally calls getBulkBarrelOwnerships concept:

```typescript
