  const month = parsedFillDate.getUTCMonth();      // 0-indexed (0=Jan, 11=Dec)
  const day = parsedFillDate.getUTCDate();

  // Determine if this date is in DST based on US Eastern timezone rules
  const isDST = this.isEasternDST(year, month, day);  // Line 3139
  const easternOffsetHours = isDST ? 4 : 5;          // Line 3140
  // EDT is UTC-4, EST is UTC-5

  // Set the dates to midnight Eastern time (which is 4 or 5 AM UTC) (lines 3142-3149)
  fillDate = new Date(
    Date.UTC(year, month, day, easternOffsetHours, 0, 0, 0),
  );
  entryTime = new Date(
    Date.UTC(year, month, day, easternOffsetHours, 0, 0, 0),
  );
