      throttlers: [
        {
          name: "short",
          ttl: 1000,          // 1 second window
          limit: 10,          // 10 requests per second (aggressive - burst protection)
        },
        {
          name: "medium",
          ttl: 10000,         // 10 second window
          limit: 50,          // 50 requests per 10 seconds (sustain-level protection)
        },
        {
          name: "long",
          ttl: 60000,         // 1 minute window
          limit: 200,         // 200 requests per minute (overall quota)
