    this.logger.debug(
      `Barrel ${barrelSN} already at location ${locationString} - allowing idempotent entry (permissive mode)`,
    );
    return { isPermissiveReentry: true, locationConflict: null };
  }

  // Strict mode: Throw error with errorToLog attached for proper classification
  const errorToLog = {
    errorLevel: EnumDeviceSyncErrorLevel.WARN,
    errorType: "BarrelReentryError",
    errorMessage: `The same Barrel (${barrelSN}) is already stored at this location: ${locationString}`,
    context: {
