### **Reentry Detection and Barrel Lookup Optimization**

When permissive reentry is detected, the service skips the expensive `findOrCreateBarrel` operation:

```
apps/whk-wms/src/barrelEvent/barrelEvent.service.ts:671-710
  // If permissive reentry was detected, we can skip barrel creation/finding
  if (locationValidationResult.isPermissiveReentry) {
    this.logger.debug(
      `[TEC-611] Permissive reentry detected - barrel already at target location, skipping barrel lookup`,
    );
    // Find the existing barrel to return it
    const existingBarrel = await transactionClient.barrel.findFirst({
      where: {
        serialNumber: barrelSN,
        locationId: storageLocation.id,
      },
    });

    if (!existingBarrel) {
      throw new BadRequestException(
        `Permissive reentry detected but barrel ${barrelSN} not found at location ${locationString}`,
      );
    }

    const eventTypeObj = await this.findEventType(
      transactionClient,
      eventTypeName,
    );
    const barrelEvent = await this.createBarrelEventRecord(
      transactionClient,
      data,
      eventTypeObj.id,
      existingBarrel.id,
    );

    return {
      barrelEvent,
      storageLocation,
      barrel: existingBarrel,
      bruteForceWarningData: null,
    };
  }

  this.logger.debug(
    `[TEC-611] No permissive reentry, calling findOrCreateBarrel`,
  );

  // Find or create barrel (may trigger brute force creation)
