### **TransferService.transfersExtended Implementation**

Once computed field sorting is detected, TransferService handles it via raw SQL:

```
apps/whk-wms/src/transfer/transfer.service.ts:47-197
  async transfersExtended(
    args: TransferFindManyArgsExtended,
  ): Promise<PrismaTransfer[]> {
    // Check if any orderBy contains computed fields requiring raw SQL
    const customerNameSort = args.orderBy?.find((o) => o.customerName);
    const transferDateSort = args.orderBy?.find((o) => o.transferDate);

    if (!customerNameSort && !transferDateSort) {
      // No computed field sorting - use standard Prisma query
      const prismaOrderBy = args.orderBy?.map((o) => {
        const { customerName, transferDate, ...rest } = o as any;
        return rest;
      });

      return this.prismaRead.transfer.findMany({
        where: args.where as Prisma.TransferWhereInput,
        orderBy: prismaOrderBy as Prisma.TransferOrderByWithRelationInput[],
        skip: args.skip,
        take: args.take,
      });
    }

    // Computed field sorting requested - use database-level expressions for efficient pagination
    // Step 1: Get matching transfer IDs (lightweight query - IDs only)
    const matchingTransfers = await this.prismaRead.transfer.findMany({
      where: args.where as Prisma.TransferWhereInput,
      select: { id: true },
      take: MAX_SORT_RECORDS,  // Safety cap: 10,000 records
    });

    if (matchingTransfers.length === 0) {
      return [];
    }

    const transferIds = matchingTransfers.map(t => t.id);
    const skip = args.skip || 0;
    const take = args.take || 10;

    // Step 2: Use raw SQL to sort by computed fields with database expressions
    const orderByParts: string[] = [];

    for (const orderEntry of args.orderBy || []) {
      const entries = Object.entries(orderEntry);
      for (const [field, direction] of entries) {
        if (!direction) continue;
        const directionStr = String(direction).toLowerCase();
        const sqlDirection = directionStr === 'asc' ? 'ASC' : 'DESC';

        if (field === 'customerName') {
          // Customer name requires JSON extraction from Customer table
          // Use explicit JSONB cast and try both 'name' and 'customerName' keys
          orderByParts.push(`LOWER(COALESCE((c.\"data\")::jsonb->>'name', (c.\"data\")::jsonb->>'customerName', '')) ${sqlDirection}`);
        } else if (field === 'transferDate') {
          // Computed transfer date using cascade: dateReceived → dateLoaded → dateEntered → createdAt
          orderByParts.push(`COALESCE(t.\"dateReceived\", t.\"dateLoaded\", t.\"dateEntered\", t.\"createdAt\") ${sqlDirection}`);
        } else {
          // Standard database columns mapped to table aliases
          const columnMap: Record<string, string> = {
            id: 't.id',
            createdAt: 't.\"createdAt\"',
            updatedAt: 't.\"updatedAt\"',
            dateReceived: 't.\"dateReceived\"',
            dateLoaded: 't.\"dateLoaded\"',
            dateEntered: 't.\"dateEntered\"',
            quantity: 't.quantity',
            customerId: 't.\"customerId\"',
            warehouseId: 't.\"warehouseId\"',
            // ... more fields
          };
          const column = columnMap[field];
          if (column) {
            orderByParts.push(`${column} ${sqlDirection}`);
          }
        }
      }
    }

    // Always add id as final tie-breaker for deterministic ordering
    if (!orderByParts.some(part => part.startsWith('t.id '))) {
      orderByParts.push('t.id ASC');
    }

    const orderByClause = orderByParts.join(', ');

    // Step 3: Use raw SQL with computed field expressions
    const sortedIds = await this.prismaRead.$queryRaw<{ id: string }[]>`
      SELECT t.id
      FROM "Transfer" t
      LEFT JOIN "Customer" c ON t."customerId" = c.id
      WHERE t.id = ANY(${transferIds})
      ORDER BY ${Prisma.raw(orderByClause)}
      LIMIT ${take} OFFSET ${skip}
    `;

    if (sortedIds.length === 0) {
      return [];
    }

    // Step 4: Fetch full transfer records for the paginated IDs
    const paginatedIds = sortedIds.map(r => r.id);
    const transfers = await this.prismaRead.transfer.findMany({
      where: { id: { in: paginatedIds } },
    });

    // Restore the sort order (Prisma's findMany doesn't preserve IN clause order)
    const transferMap = new Map(transfers.map(t => [t.id, t]));
    return paginatedIds.map(id => transferMap.get(id)!).filter(Boolean);
  }
```

