### **4. Azure AD Strategy: Fallback in Chain**

**apps/whk-wms/src/auth/azure-ad.strategy.ts:32-78** - Constructor with JWKS configuration:
```typescript
@Injectable()
export class AzureAdStrategy extends PassportStrategy(Strategy, \"azure-ad\") {
  constructor(
    private configService: ConfigService,
    private azureAdService: AzureAdService,
    private userRegistrationService: UserRegistrationService,
  ) {
    const tenantId = configService.get<string>(\"AZURE_TENANT_ID\");
    const v2JwksUri = `https://login.microsoftonline.com/${tenantId}/discovery/v2.0/keys`;
    const v1JwksUri = `https://login.microsoftonline.com/${tenantId}/discovery/keys`;
    const v2Client = new JwksClient({...});
    const v1Client = new JwksClient({...});

    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      secretOrKeyProvider: async (
        _req: Request,
        rawJwtToken: string,
        done: (err: Error | null, key?: string) => void,
      ) => {
        // Try v2 JWKS first, fallback to v1
        try {
          const key = await v2Client.getSigningKey(kid);
          return done(null, key.getPublicKey());
        } catch (e) {
          const key = await v1Client.getSigningKey(kid);
          return done(null, key.getPublicKey());
        }
      },
      issuer: AzureAdStrategy.buildAllowedIssuers(...),
      audience: AzureAdStrategy.buildAllowedAudiences(...),
      ignoreExpiration: false,
      algorithms: [\"RS256\"],
    });
  }
```

Azure AD Strategy configuration:
- **Token Extraction**: Same as JWT - `ExtractJwt.fromAuthHeaderAsBearerToken()`
- **Key Resolution**: Uses JwksClient to fetch signing keys from Azure JWKS endpoints (tries v2 first, falls back to v1)
- **Issuer Validation**: Validates token issuer against allowed Azure issuers (both v1 `sts.windows.net` and v2 `login.microsoftonline.com`)
- **Audience Validation**: Validates token audience against configured client IDs

**apps/whk-wms/src/auth/azure-ad.strategy.ts:183-274** - Validate method with multi-path logic:
```typescript
async validate(
  req: Request,
  payload: AzureJwtPayload,
): Promise<AuthenticatedUser> {
  // Validate issuer
  const allowedIssuers = AzureAdStrategy.buildAllowedIssuers(...);
  if (!allowedIssuers.includes(tokenIssuer)) {
    throw new UnauthorizedException(\"Invalid token issuer\");
  }

  // Validate audience
  const allowedAudiences = AzureAdStrategy.buildAllowedAudiences(...);
  if (!hasAllowedAudience) {
    throw new UnauthorizedException(\"Invalid token audience\");
  }

  // Detect token type: delegated user token vs application token
  const isDelegatedUserToken = typeof rawAny.scp === \"string\" && rawAny.scp.length > 0;
  const isApplicationToken = !isDelegatedUserToken && (Array.isArray(rawAny.roles) || ...);

  // For application tokens (client credentials) - skip user registration
  if (isApplicationToken) {
    // Check allowlist, extract appid, create service user
    return serviceUser;
  }

  // For delegated user tokens - full registration flow
  const validationResult = await this.azureAdService.validateTokenAndGetUser(token);
  const registrationResult = await this.userRegistrationService.registerOrUpdateUser(...);

  return {
    id: registrationResult.user.id,
    userId: resolvedUserId,
    username: registrationResult.user.username,
    roles: registrationResult.rolesAssigned,
    ...
  };
}
```

The Azure AD validate method throws `UnauthorizedException` if validation fails, signaling Passport to fall back to other strategies (if any remain).

