### **8. Dynamic WHERE Clause Builder**

**apps/whk-wms/src/barrelSnapshot/barrel-snapshot.service.ts:255-289**:
```typescript
private buildWhereClause(filters: FiltersConfig): {
  whereClause: string;
  queryParams: any[];
} {
  const whereConditions: string[] = [];
  const queryParams: any[] = [];

  for (const [key, value] of Object.entries(filters)) {
    if (!this.isValidColumnKey(key)) {
      throw new BadRequestException(`Filtering by '${key}' is not supported`);
    }

    const columnName = this.COLUMN_MAPPING[key as AllowedColumnKey];

    if (typeof value === "string") {
      // Escape special characters in the search string
      const escapedValue = value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      whereConditions.push(`${columnName} ILIKE $${queryParams.length + 1}`);
      queryParams.push(`%${escapedValue}%`);
    } else {
      whereConditions.push(`${columnName} = $${queryParams.length + 1}`);
      queryParams.push(value);
    }
  }

  const whereClause = whereConditions.length > 0
    ? `WHERE ${whereConditions.join(" AND ")}`
    : "";

  return { whereClause, queryParams };
}
```

Filters support both exact matches (numbers) and pattern matching (strings with ILIKE), with proper escaping for security.

