```typescript
private async validateCsvStructure(file: any): Promise<void> {
  return new Promise((resolve, reject) => {
    const maxRowsToCheck = 10; // Only check first 10 rows
    const validationTimeout = 5000; // 5 second timeout
    let headerValidated = false;

    // Convert buffer to string and create stream
    const csvContent = file.buffer.toString("utf-8");

    Readable.from([csvContent])
      .pipe(csv())
      .on("data", (data: any) => {
        // Validate headers on first row only
        if (isFirstRow) {
          const headers = Object.keys(data);
          const cleanHeaders = headers.map((h) => 
            h.replace(/^\uFEFF/, "").trim()
          );

          // Check for required headers (case-insensitive)
          const missingHeaders = this.requiredHeaders.filter(
            (req) => !cleanHeaders.some(
              (h) => h.toLowerCase() === req.toLowerCase()
            )
          );

          if (missingHeaders.length > 0) {
            throw new Error(
              `Missing required headers: ${missingHeaders.join(", ")}`
            );
          }
          headerValidated = true;
        }

        // Stop after 10 rows to avoid lengthy validation
        if (headerValidated && rowCount >= 10) {
          stream.destroy();
          resolve();
        }
      });
  });
}
```

