### Stage 5: Streaming CSV to Staging Table

The `CsvParsingService.streamToStaging()` at `apps/whk-wms/src/inventory-upload/csv-parsing.service.ts:304-646` handles the actual transformation:

```typescript
async streamToStaging(
  filePath: string,
  sessionId: string,
  enableSchemaValidation = false,
): Promise<StreamResult> {
  const client = await this.pgPool.connect();

  try {
    await client.query("BEGIN");

    let rowNumber = 0;
    const batchData: any[] = [];

    // Create Transform stream for data mapping
    const transformStream = new Transform({
      objectMode: true,
      transform(chunk: any, encoding, callback) {
        // Verify headers on first chunk
        if (!headersParsed) {
          const headers = Object.keys(chunk);
          const cleanHeaders = headers.map(h => 
            h.replace(/^\uFEFF/, "").trim()
          );
          headersParsed = true;
        }

        rowNumber++;

        // Perform Zod schema validation if enabled (lines 373-412)
        if (enableSchemaValidation) {
          const validationResult = schemaValidation.validateSingleRow(
            zodRow,
            rowNumber,
          );
          if (!validationResult.isValid) {
            // Skip invalid rows but continue processing
            callback();
            return;
          }
        }

        // Map CSV columns to staging table columns
        // Normalize warehouse variations (line 425)
        let warehouseValue = chunk[findChunkKey("Warehouse")];
        if (warehouseValue && /^Blending\s+House$/i.test(warehouseValue)) {
          warehouseValue = "BlendingHouse";
        }

        const rowData = {
          uploadSessionId: sessionId,
          rowNumber,
          Notes: chunk[findChunkKey("Notes")]?.trim() || null,
          Customer: chunk[findChunkKey("Customer")]?.trim() || null,
          Warehouse: warehouseValue,
          Floor: chunk[findChunkKey("Floor")]?.trim() || null,
          Tier: chunk[findChunkKey("Tier")]?.trim() || null,
          Rick: chunk[findChunkKey("Rick")]?.trim() || null,
          Position: chunk[findChunkKey("Position")]?.trim() || null,
          LotNumber: chunk[findChunkKey("Lot#")]?.trim() || null,
          Mashbill: chunk[findChunkKey("Mashbill")]?.trim() || null,
          BarrelNumber: chunk[findChunkKey("Barrel#")]?.trim() || null,
        };

        callback(null, rowData);
      }
    });

    // Stream file through pipeline
    const stream = createReadStream(filePath)
      .pipe(csv()) // csv-parser handles column parsing
      .pipe(transformStream);

    // Collect transformed data
    for await (const chunk of stream) {
      if (chunk) {
        batchData.push(chunk);
      }
    }

    // Batch insert to database
    if (batchData.length > 0) {
      await this.prisma.inventoryUploadStaging.createMany({
        data: batchData,
        skipDuplicates: true,
      });
    }

    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw new BadRequestException(`Failed to process CSV: ${error.message}`);
  } finally {
    client.release();
  }
}
```

**Key transformation features:**
- **Stream-based processing** (line 369): Uses Node.js streams to avoid loading entire file into memory
- **Row-by-row transformation** (lines 381-411): Maps CSV columns to database columns
- **Selective validation** (line 373): Optional Zod schema validation for data integrity
- **Batch collection** (line 583): Collects transformed rows for efficient `createMany()` insert
- **Transaction wrapper** (lines 318, 612): ACID semantics for reliability

### Stage 6: Batch Processing with Safety Limits

The `InventoryProcessingProcessor.processInventorySession()` at `apps/whk-wms/src/inventory-upload/inventory-processing.processor.ts:100-658` handles batch processing:

```typescript
@Process("process-inventory-session")
async processInventorySession(
  job: Job<{ sessionId: string; batchSize: number }>,
): Promise<void> {
  const { sessionId, batchSize } = job.data;

  // Initialize session metrics
  if (!this.sessionMetrics.has(sessionId)) {
    this.sessionMetrics.set(sessionId, {
      consecutiveEmptyBatches: 0,
      consecutiveErrors: 0,
      startTime: new Date(),
    });
  }

  // Check safety limits BEFORE processing (lines 127-158)
  const safetyCheck = await this.safetyLimitsService.checkSafetyLimits(
    sessionId,
    batchNumber,
    metrics.consecutiveEmptyBatches,
    metrics.consecutiveErrors,
    metrics.startTime,
  );

  if (!safetyCheck.canContinue) {
    throw new Error(`Safety limit reached: ${safetyCheck.reason}`);
  }

  // Check resource limits (lines 170-177)
  const resourceCheck = await this.safetyLimitsService.checkResourceLimits(
    sessionId
  );
  if (resourceCheck.shouldAbort) {
    await this.safetyLimitsService.emergencyStop(sessionId, resourceCheck.reason);
    throw new Error(resourceCheck.reason);
  }

  // Process batch via SQL function (line 219)
  const batchResult = await this.inventoryProcessingService.processBatch(
    sessionId,
    batchSize,
  );

  // Update metrics based on results (lines 235-261)
  if (batchResult.processedCount === 0) {
    metrics.consecutiveEmptyBatches++;
  } else {
    metrics.consecutiveEmptyBatches = 0;
  }

  // Continuation logic (lines 315-371)
  const shouldContinue = 
    batchResult.processedCount > 0 ||
    stillHasPending > 0 ||
    (checkpoint?.remainingWork?.totalRemaining || 0) > 0;

  if (shouldContinue) {
    // Queue next batch instead of recursion
    await this.processingQueue.add(
      "process-inventory-session",
      { sessionId, batchSize },
      {
        attempts: 3,
        backoff: { type: "exponential", delay: 2000 },
        removeOnComplete: true,
        removeOnFail: false,
      }
    );
    return;
  }

  // All batches complete - run Trust Mode if enabled (lines 387-432)
  if (sessionForTrustMode?.trustModeEnabled) {
    const trustModeResult = 
      await this.trustModeProcessingService.processBarrelsForTrustMode(
        sessionId,
        [],
        { userId: sessionForTrustMode.uploadedBy, correlationId },
        sessionForTrustMode.trustModeCutoffDate,
      );
  }
}
```

