### Stage 7: SQL-Level Batch Processing

The `processBatch()` method at `apps/whk-wms/src/inventory-upload/inventory-processing.service.ts:1211-1446` invokes PostgreSQL:

```typescript
async processBatch(
  sessionId: string,
  batchSize: number,
): Promise<BatchResult> {
  // Call PostgreSQL function that processes entire batch atomically
  const result = await this.prisma.$queryRaw<
    { process_inventory_batch: any }[]
  >`
    SELECT process_inventory_batch(${sessionId}::text, ${batchSize}::integer)
  `;

  const batchResponse = result[0].process_inventory_batch;

  // Extract statistics from response (lines 1253-1297)
  const details = batchResponse.details;
  const processedCount = details.processingResults?.totalProcessed || 0;
  const successCount = 
    (details.processingResults?.barrelsCreated || 0) +
    (details.processingResults?.barrelsUpdated || 0);
  const errorCount = details.processingResults?.errors || 0;

  // Transform barrel details results (lines 1307-1368)
  let barrelDetailsResults: BarrelDetailsResult[] = [];
  if (details.barrelDetailsResults && 
      Array.isArray(details.barrelDetailsResults)) {
    barrelDetailsResults = details.barrelDetailsResults.map((dbResult: any) => ({
      barrelId: dbResult.barrelId || "unknown",
      operationType: dbResult.operationType === "created" ? "created" : "updated",
      success: dbResult.success === true,
      errorMessage: dbResult.errorMessage || undefined,
      details: {
        lotCodeParsing: { /* ... */ },
        cooperageParsing: { /* ... */ },
        barrelSpecsParsing: { /* ... */ },
        customerCodeLookup: { /* ... */ }
      }
    }));
  }

  // Build checkpoint for progress tracking (lines 1370-1383)
  const batchResult: BatchResult = {
    batchNumber: details.batchNumber || 1,
    processedCount,
    successCount,
    errorCount,
    skippedCount: 0,
    barrelDetailsResults,
    checkpoint: details.checkpoint ? {
      totalRows: details.checkpoint.totalRows,
      processedSoFar: details.checkpoint.processedSoFar,
      percentComplete: details.checkpoint.percentComplete,
      remainingWork: {
        unvalidatedRecords: details.remainingPending || 0,
        validatedPendingProcessing: details.remainingValidated || 0,
        totalRemaining: details.totalRemaining || 0
      }
    } : undefined
  };

  return batchResult;
}
```

### Data Transformation Summary

| Stage | Input | Output | Purpose |
|-------|-------|--------|---------|
| **Upload** | File bytes (100MB max) | File validation errors or upload session | Prevent invalid files from entering system |
| **Streaming** | CSV rows | InventoryUploadStaging table | Transform CSV schema to database schema |
| **Validation** | Staging records | Validated/error flags | Check business rules and data quality |
| **Processing** | Validated records | Barrel, BarrelAudit, BarrelEvent rows | Create/update barrel entities |
