private sanitizeForAudit(data: any): any {
  if (!data || typeof data !== "object") {
    return data;
  }

  // Fields to exclude from audit logs for security/privacy
  const excludedFields = [
    "password",
    "passwordHash",
    "salt",
    "token",
    "secret",
    "apiKey",
    "privateKey",
  ];

  const sanitized = { ...data };

  // Remove excluded fields
  excludedFields.forEach((field) => {
    delete sanitized[field];
  });

  // Convert dates to ISO strings for consistent storage
  Object.keys(sanitized).forEach((key) => {
    if (sanitized[key] instanceof Date) {
      sanitized[key] = sanitized[key].toISOString();
    }
  });

  return sanitized;
}
```

