**Local invalidation** at lines 218-240 removes all name variants for a type ID:

```typescript
private performLocalInvalidation(typeId: string): void {
  // Find ALL name variants associated with this type ID
  const nameVariants = this.idToNameMap.get(typeId);  // Line 223

  if (!nameVariants || nameVariants.size === 0) {
    this.logger.debug(`No cache entries found for event type ID: ${typeId}`);
    return;
  }

  // Delete ALL cache entries for all name variants
  let deletedCount = 0;
  for (const name of nameVariants) {
    this.eventTypeCache.delete(name);       // Line 233
    this.cacheTimestamps.delete(name);      // Line 234
    deletedCount++;
  }

  // Remove the ID mapping
  this.idToNameMap.delete(typeId);          // Line 238

  this.logger.debug(
    `Locally invalidated cache for event type ID ${typeId}: removed ${deletedCount} variant(s)`,  // Line 241
  );
}
```

**Distributed invalidation** at lines 246-264 publishes to Redis:

```typescript
private async emitDistributedInvalidation(typeId: string): Promise<void> {
  if (!this.pubSubProvider) {
    return; // No Redis, skip distributed invalidation
  }

  try {
    const pubSub = this.pubSubProvider.getInstance();
    await pubSub.publish(this.CACHE_INVALIDATION_CHANNEL, {  // Line 259
      typeId,
      timestamp: Date.now(),
    });

    this.logger.debug(
