function getDevOverride(flagKey: FeatureFlagKey): boolean | null {
  if (typeof window === 'undefined') {
    // Server-side: check environment variables
    const overrideKey = `NEXT_PUBLIC_OVERRIDE_${flagKey.toUpperCase().replace(/-/g, '_')}`;
    const override = process.env[overrideKey];
    return override !== undefined ? override === 'true' : null;
  } else {
