  private idToNameMap = new Map<string, Set<string>>(); // Reverse index
  private readonly CACHE_TTL_MS = 10 * 60 * 1000; // 10 minutes
  private readonly CACHE_INVALIDATION_CHANNEL = 'cache:invalidate:event-type';
