private validateInspectionPayload(jsonEntityPayload: any): InspectionPayload {
  // Accepts both string and object payloads
  let parsedPayload: any;
  if (typeof jsonEntityPayload === "string") {
    try {
      parsedPayload = JSON.parse(jsonEntityPayload);  // Parse JSON if string
    } catch (parseError) {
      throw new BadRequestException(
        `Invalid Inspection request: jsonEntityPayload contains invalid JSON string...`
      );
    }
  } else if (typeof jsonEntityPayload === "object") {
    parsedPayload = jsonEntityPayload;  // Use object directly
  }

  // Enforce required field: repairReason
  if (!parsedPayload.repairReason) {
    const availableFields = Object.keys(parsedPayload);
    throw new BadRequestException(
      `Invalid Inspection payload: Missing required field 'repairReason'. ` +
        `Available fields: [${availableFields.join(", ")}]...`
    );
  }

  // Class-validator validation
  const payload = plainToInstance(InspectionPayload, parsedPayload);
  const errors = validateSync(payload);
  if (errors.length > 0) {
    const errorMessages = errors
      .map((error) => {
        const constraints = error.constraints ? Object.values(error.constraints) : [];
        return `Field '${error.property}': ${constraints.join(", ")}`;
      })
      .join("; ");
    throw new BadRequestException(
      `Invalid Inspection payload validation: ${errorMessages}`
    );
  }
  return payload;  // Type-safe InspectionPayload
}
```

